-- Analytics historically exposed membership.started_at while the foundation schema called the
-- same moment created_at. Keep the API contract compatible without rewriting old data.
ALTER TABLE workspace_memberships ADD COLUMN IF NOT EXISTS started_at timestamptz;
UPDATE workspace_memberships SET started_at=created_at WHERE started_at IS NULL;
ALTER TABLE workspace_memberships ALTER COLUMN started_at SET DEFAULT now();

-- Curated gym-language names for the beginning of the catalogue and common movements.
-- These are intentionally not literal machine translations: they use names people actually
-- recognize in Ukrainian/Russian gyms. Existing descriptions/instructions are preserved.
WITH names(legacy_key,uk,ru) AS (VALUES
 ('0001','Скручування 3/4','Скручивания 3/4'),
 ('0002','Бічні нахили 45°','Боковые наклоны 45°'),
 ('0003','Велосипед лежачи','Велосипед лёжа'),
 ('1512','Розтягування квадрицепса навкарачки','Растяжка квадрицепса на четвереньках'),
 ('0006','Почергові дотики до п’ят','Поочерёдные касания пяток'),
 ('0007','Почергова тяга верхнього блока','Попеременная тяга верхнего блока'),
 ('1368','Колові рухи стопою','Круговые движения стопой'),
 ('3293','Підтягування лучника','Подтягивания лучника'),
 ('3294','Віджимання лучника','Отжимания лучника'),
 ('0009','Віджимання на брусах у гравітроні (з колін)','Отжимания на брусьях в гравитроне (с колен)'),
 ('0011','Підйом колін у висі з підтримкою','Подъём коленей в висе с поддержкой'),
 ('0010','Підйом колін у висі з кидком ніг вниз','Подъём коленей в висе с броском ног вниз'),
 ('1708','Розтягування литок лежачи з підтримкою','Растяжка икр лёжа с поддержкой'),
 ('1709','Розтягування сідниць лежачи з підтримкою','Растяжка ягодиц лёжа с поддержкой'),
 ('1710','Розтягування сідниць і грушоподібного м’яза','Растяжка ягодиц и грушевидной мышцы'),
 ('0012','Підйом прямих ніг лежачи з опусканням убік','Подъём прямых ног лёжа с опусканием в сторону'),
 ('0013','Підйом прямих ніг лежачи з кидком вниз','Подъём прямых ног лёжа с броском вниз'),
 ('0014','Російські скручування з медболом','Русские скручивания с медболом'),
 ('0015','Підтягування вузьким паралельним хватом у гравітроні','Подтягивания узким параллельным хватом в гравитроне'),
 ('0016','Згинання ніг лежачи з підтримкою','Сгибание ног лёжа с поддержкой'),
 ('0027','Тяга штанги в нахилі','Тяга штанги в наклоне'),
 ('0293','Тяга гантелей у нахилі','Тяга гантелей в наклоне'),
 ('0499','Австралійські підтягування','Австралийские подтягивания'),
 ('0861','Тяга нижнього блока сидячи','Тяга нижнего блока сидя'),
 ('0047','Жим штанги лежачи','Жим штанги лёжа'),
 ('0289','Жим гантелей лежачи','Жим гантелей лёжа'),
 ('0025','Присідання зі штангою','Приседания со штангой'),
 ('0032','Станова тяга зі штангою','Становая тяга со штангой'),
 ('0095','Підйом штанги на біцепс','Подъём штанги на бицепс'),
 ('0241','Французький жим лежачи','Французский жим лёжа')
)
INSERT INTO exercise_translations(exercise_id,locale,name,description,instructions)
SELECT e.id,'uk',n.uk,NULL,NULL FROM names n JOIN exercises e ON e.legacy_key=n.legacy_key
ON CONFLICT(exercise_id,locale) DO UPDATE SET name=EXCLUDED.name;

